/// @param data   Pointer to byte buffer to read into.
/// @param size   Maximum number of bytes to read.
/// @return The number of bytes actually read (see std::istream::gcount()).
///
inline std::streamsize readBytes(std::istream& stream, uint8_t* const data, const std::size_t size)
{
   // std::istream::read only accepts char*, but our buffers are uint8_t. Casting
   // between them is safe: the C++ standard lets you view any object as a sequence
   // of bytes (char, unsigned char, or std::byte), and uint8_t is just unsigned
   // char on every platform we support. This helper keeps the cast (and its


   stream.read(reinterpret_cast<char*>(data), static_cast<std::streamsize>(size));
   return stream.gcount();
}

