/// @brief Reads from a char-oriented input stream into a byte buffer at the
/// given offset.
///
/// Convenience overload that centralises the offset pointer arithmetic for
/// callers that need to fill the tail of a pre-allocated contiguous buffer.
///
/// @param stream Input stream to read from.
/// @param data   Pointer to a contiguous byte buffer of at least
///               @p offset + @p size bytes.
/// @param offset Index at which to start writing within the buffer.
/// @param size   Maximum number of bytes to read.
/// @return The number of bytes actually read (see std::istream::gcount()).
///
inline std::streamsize readBytes(
   std::istream& stream,
   uint8_t* const data,
   const std::size_t offset,
   const std::size_t size)
{
   // Pointer arithmetic safe by caller-validated bounds precondition.

   return readBytes(stream, data + offset, size);
}

