double calculateMslmMapping(const double elevationAngleRadians)
{
   // Reference: Schaer, S. Mapping and Predicting the Earth's Ionosphere Using the Global
   // Positioning System. Ph.D. Thesis, University of Berne, Bern, Switzerland, 1999.
   const double zenithAngle = bmc::half_pi<double>() - elevationAngleRadians;
   constexpr double radiusRatio = (6371e3 / (6371e3 + 506.7e3));
   constexpr double alpha = 0.9782;
   return 1.0 / std::sqrt(1.0 - square(radiusRatio * std::sin(alpha * zenithAngle)));
}
